/**
 * Splits a bill between people, in cents. The shares always add up to the total: when it doesn't
 * divide evenly, the first people pay one cent more.
 */
export function split(totalCents: number, people: number): number[] {
  if (!Number.isInteger(totalCents) || totalCents < 0) {
    throw new RangeError("totalCents must be a whole number of cents, 0 or more");
  }
  if (!Number.isInteger(people) || people < 1) {
    throw new RangeError("people must be a whole number, 1 or more");
  }
  const base = Math.floor(totalCents / people);
  const remainder = totalCents - base * people;
  return Array.from({ length: people }, (_, i) => base + (i < remainder ? 1 : 0));
}

/** Splits a bill by each person's weight, such as the number of dishes they had. */
export function splitUneven(totalCents: number, weights: number[]): number[] {
  if (!Number.isInteger(totalCents) || totalCents < 0) {
    throw new RangeError("totalCents must be a whole number of cents, 0 or more");
  }
  if (weights.some((weight) => !Number.isInteger(weight) || weight < 0)) {
    throw new RangeError("each weight must be a whole number, 0 or more");
  }
  const totalWeight = weights.reduce((sum, weight) => sum + weight);
  const shares = weights.map((weight) => Math.floor((totalCents * weight) / totalWeight));
  let left = totalCents - shares.reduce((sum, share) => sum + share, 0);
  for (let i = 0; left > 0; i++, left--) shares[i % shares.length] += 1;
  return shares;
}

