import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { split, splitUneven } from "./split.ts";

describe("split", () => {
  it("divides an even bill equally", () => {
    assert.deepEqual(split(3000, 3), [1000, 1000, 1000]);
  });

  it("gives the leftover cents to the first people, so nothing is lost", () => {
    assert.deepEqual(split(1000, 3), [334, 333, 333]);
  });

  it("rejects fractions of a cent and nobody to pay", () => {
    assert.throws(() => split(10.5, 2), RangeError);
    assert.throws(() => split(1000, 0), RangeError);
  });
});

describe("splitUneven", () => {
  it("splits by weight", () => {
    assert.deepEqual(splitUneven(1000, [2, 1, 1]), [500, 250, 250]);
  });

  it("keeps the shares adding up when the bill doesn't divide exactly", () => {
    assert.deepEqual(splitUneven(1000, [1, 1, 1]), [334, 333, 333]);
  });

  it("matches split when everyone has the same weight", () => {
    assert.deepEqual(splitUneven(3000, [1, 1, 1]), split(3000, 3));
  });

  it("refuses a negative weight", () => {
    assert.throws(() => splitUneven(1000, [1, -1]), RangeError);
  });
});
